args:
'f="$1"; row="$2"; mode="$3"
case "$f" in
  */game/*) p="${f%/game/*}"; rel="game/${f##*/game/}" ;;
  *) echo "$f is not inside a game/ folder" >&2; exit 1 ;;
esac
sdk="${RENPY_SDK:-}"
if [ -n "$sdk" ] && [ -f "$sdk" ]; then sdk=$(dirname "$sdk"); fi
if [ -n "$sdk" ]; then
  if [ ! -f "$sdk/renpy.sh" ]; then
    echo "RENPY_SDK is set but $sdk does not contain renpy.sh." >&2
    exit 1
  fi
else
  sdk=$(find "$HOME" "$HOME/Documents" "$HOME/Downloads" "$HOME/Desktop" "$HOME/Applications" /Applications -maxdepth 1 -type d -name "renpy-*-sdk" 2>/dev/null | sort -V | tail -n 1)
  if [ -z "$sdk" ] || [ ! -f "$sdk/renpy.sh" ]; then
    echo "Ren-Py SDK not found. Set RENPY_SDK to the SDK folder, the one containing renpy.sh." >&2
    exit 1
  fi
fi
case "$mode" in
  run) set -- "$p" run ;;
  warp) set -- "$p" run --warp "$rel:$row" ;;
  lint) set -- "$p" lint ;;
  compile) set -- "$p" compile ;;
  dialogue) set -- "$p" dialogue None ;;
  rmpersistent) set -- "$p" rmpersistent ;;
  *) echo "Unknown Ren-Py task mode: $mode" >&2; exit 1 ;;
esac
exec "$sdk/renpy.sh" "$@"'

